function lineDiff(before,after){if(before===after)return el('pre',{},after);const old=before.split('\n'),next=after.split('\n');let start=0;while(start<old.length&&start<next.length&&old[start]===next[start])start++;let end=0;while(end<old.length-start&&end<next.length-start&&old.at(-end-1)===next.at(-end-1))end++;const out=el('pre');if(start)out.append(el('span',{class:'muted'},tr('相同的前 ','Unchanged first ')+start+tr(' 行\n',' lines\n')));old.slice(start,old.length-end).forEach(t=>out.append(el('span',{class:'diff-del'},'- '+t)));next.slice(start,next.length-end).forEach(t=>out.append(el('span',{class:'diff-add'},'+ '+t)));if(end)out.append(el('span',{class:'muted'},tr('相同的末尾 ','Unchanged last ')+end+tr(' 行',' lines')));return out;}
